namespace TailscaleAuto {
public class Device {
 public string Id,Name,OS,IP,Path="未确认",Checked="—",LatencyMs="—",CurAddr; public bool Online,OnlineKnown,Self;public long Generation;public LanRdpResult Lan;
 public bool Windows {get{return String.Equals(OS,"windows",StringComparison.OrdinalIgnoreCase);}}
 public bool CanRdp {get{IPAddress ip;return !Self&&Online&&OnlineKnown&&Windows&&PathConfirmed&&IPAddress.TryParse(IP,out ip);}}
 public bool PathConfirmed {get{return Path=="直连"||Path.StartsWith("中继");}}
 public Device Copy(){return (Device)MemberwiseClone();}
}
public class Snapshot {public List<Device> Devices=new List<Device>();public string Message;public bool Valid;public DateTime ListUpdated;}
public class CommandResult {public int Exit;public string Output,Error;public bool TimedOut;}
public static class Core {
 static object Get(Dictionary<string,object> d,string k){object v;return d.TryGetValue(k,out v)?v:null;}
 static string Str(Dictionary<string,object>d,string k){return Convert.ToString(Get(d,k));}
 static string MachineName(Dictionary<string,object>d){string dns=Str(d,"DNSName").TrimEnd('.');if(!String.IsNullOrWhiteSpace(dns)){int dot=dns.IndexOf('.');return dot>0?dns.Substring(0,dot):dns;}return Str(d,"HostName");}
 static Device ParseDevice(Dictionary<string,object>d,bool self,string id){var ips=Get(d,"TailscaleIPs") as IEnumerable;var addresses=ips==null?new string[0]:ips.Cast<object>().Select(Convert.ToString).ToArray();object online=Get(d,"Online");return new Device{Id=id,Name=MachineName(d),OS=Str(d,"OS"),IP=addresses.FirstOrDefault(x=>x.IndexOf(':')<0)??addresses.FirstOrDefault()??"",CurAddr=Str(d,"CurAddr"),Online=online is bool&&(bool)online,OnlineKnown=online is bool,Self=self,Path=self?"本机（不适用）":"未确认"};}
 public static Snapshot ParseStatus(string json){var root=new JavaScriptSerializer{MaxJsonLength=16*1024*1024}.Deserialize<Dictionary<string,object>>(json);var s=new Snapshot();string state=Str(root,"BackendState");if(state!="Running"){s.Message="Tailscale 未就绪："+state+"。请在 Tailscale 客户端检查服务和登录状态。";return s;}var self=Get(root,"Self") as Dictionary<string,object>;if(self!=null)s.Devices.Add(ParseDevice(self,true,"self"));var peers=Get(root,"Peer") as Dictionary<string,object>;if(peers!=null)foreach(var p in peers){var d=p.Value as Dictionary<string,object>;if(d!=null)s.Devices.Add(ParseDevice(d,false,p.Key));}s.Valid=true;s.ListUpdated=DateTime.Now;s.Message="设备清单更新于 "+DateTime.Now.ToString("HH:mm:ss");return s;}
 static long generation;
 public static Snapshot CarryPaths(Snapshot old,Snapshot next){if(!next.Valid)return next;foreach(var d in next.Devices){if(d.Self||!d.OnlineKnown||!d.Online){d.Path=d.Self?"本机（不适用）":"无当前路径";d.Checked="—";d.LatencyMs="—";d.Generation=Interlocked.Increment(ref generation);continue;}var prior=old.Valid?old.Devices.FirstOrDefault(x=>x.Id==d.Id&&x.IP==d.IP&&x.OnlineKnown&&x.Online&&!x.Self):null;if(prior!=null){d.Path=prior.Path;d.Checked=prior.Checked;d.LatencyMs=prior.LatencyMs;if(d.CurAddr==prior.CurAddr&&d.Windows)d.Lan=prior.Lan;d.Generation=prior.Generation;}else d.Generation=Interlocked.Increment(ref generation);}return next;}
 public static string ParsePath(string output){string result="无法确认";foreach(string raw in (output??"").Split('\n')){string line=raw.Trim();if(!Regex.IsMatch(line,@"^pong from .+ via .+ in [0-9.]+(ms|s)$"))continue;if(Regex.IsMatch(line,@" via DERP\([^)]+\) in "))result="中继（DERP）";else if(Regex.IsMatch(line,@" via (peer-relay|PeerRelay|relay)\b",RegexOptions.IgnoreCase))result="中继";else if(Regex.IsMatch(line,@" via (\[[0-9a-fA-F:]+\]|[0-9.]+):[0-9]+ in "))result="直连";else result="无法确认";}return result;}
 public static string ParseLatency(string output){var m=Regex.Match(output??"",@"\bin\s+([0-9]+(?:\.[0-9]+)?)(ms|s)\b",RegexOptions.IgnoreCase);if(!m.Success)return "—";double value;if(!Double.TryParse(m.Groups[1].Value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value))return "—";if(String.Equals(m.Groups[2].Value,"s",StringComparison.OrdinalIgnoreCase))value*=1000;return Math.Round(value,1).ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+" ms";}
 public static List<Device> SortDevices(IEnumerable<Device> source,Func<Device,string> displayName){return source.OrderBy(d=>d.Self?0:(d.OnlineKnown&&d.Online?1:2)).ThenBy(d=>displayName(d)??"",StringComparer.OrdinalIgnoreCase).ToList();}
 public static string DisplayOS(string os){switch((os??"").Trim().ToLowerInvariant()){case "windows":return "Windows";case "android":return "Android";case "ios":case "ipados":return "IOS";case "macos":case "darwin":return "macOS";case "linux":return "Linux";case "":return "未知系统";default:return os.Trim();}}
 public static string RdpArguments(Device d){if(!d.CanRdp)throw new InvalidOperationException("仅在线 Windows 其他设备可使用远程桌面");return "/v:"+d.IP;}
 public static Rectangle VisibleBounds(Rectangle r,Rectangle[] screens){if(screens.Any(x=>x.Contains(r)))return r;Rectangle b=screens[0];r.Width=Math.Min(r.Width,b.Width);r.Height=Math.Min(r.Height,b.Height);r.X=Math.Max(b.Left,Math.Min(r.X,b.Right-r.Width));r.Y=Math.Max(b.Top,Math.Min(r.Y,b.Bottom-r.Height));return r;}
 public static CommandResult Run(string exe,string args,int timeout,CancellationToken token){var p=new Process{StartInfo=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8}};try{p.Start();Task<string> stdout=p.StandardOutput.ReadToEndAsync(),stderr=p.StandardError.ReadToEndAsync();var watch=Stopwatch.StartNew();while(!p.WaitForExit(100)){if(token.IsCancellationRequested||watch.ElapsedMilliseconds>timeout){try{p.Kill();}catch{}p.WaitForExit(1000);return new CommandResult{Exit=-1,TimedOut=true,Output="",Error=token.IsCancellationRequested?"已取消":"命令超时"};}}return new CommandResult{Exit=p.ExitCode,Output=stdout.Result,Error=stderr.Result};}finally{p.Dispose();}}
}
public class Settings {
 [ScriptIgnore] public bool Persist=true; public bool Floating=true; public int X=60,Y=60,Opacity=70,DefaultsVersion; public string Language="en";
 [ScriptIgnore] public bool PendingDefaultsSave; public Dictionary<string,string> Aliases=new Dictionary<string,string>();
 public string DisplayName(Device d){string a;return Aliases!=null&&Aliases.TryGetValue(d.Id??"",out a)&&!String.IsNullOrWhiteSpace(a)?new string(a.Where(c=>!Char.IsControl(c)).ToArray()):d.Name;}
 public static string FilePath=DefaultPath();
 static string DefaultPath(){return System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings.json");}
 public static Settings Load(){Settings value;try{value=new JavaScriptSerializer().Deserialize<Settings>(File.ReadAllText(FilePath))??new Settings();}catch{value=new Settings();}if(value.Aliases==null)value.Aliases=new Dictionary<string,string>();if(value.Language!="zh-CN")value.Language="en";if(value.DefaultsVersion<142){value.Floating=true;value.Opacity=70;value.DefaultsVersion=142;value.PendingDefaultsSave=true;}return value;}
 [ScriptIgnore] public string LastSaveError; [ScriptIgnore] public bool SaveWarningRaised; public event Action<string> SaveFailed; public event Action SaveRecovered;
 public bool Save(){if(!Persist)return true;try{Directory.CreateDirectory(System.IO.Path.GetDirectoryName(FilePath));File.WriteAllText(FilePath,new JavaScriptSerializer().Serialize(this),Encoding.UTF8);PendingDefaultsSave=false;bool recovered=LastSaveError!=null;LastSaveError=null;SaveWarningRaised=false;if(recovered){var h=SaveRecovered;if(h!=null)h();}return true;}catch(Exception ex){LastSaveError=ex.Message;if(!SaveWarningRaised){SaveWarningRaised=true;var h=SaveFailed;if(h!=null)h(LastSaveError);}return false;}}
}
public class Monitor : IDisposable {
 public event Action<Snapshot> Changed;CancellationTokenSource stop=new CancellationTokenSource();System.Threading.Timer timer;int busy,disposed;public string Exe;public int Rounds;readonly object sync=new object();Snapshot current=new Snapshot();Queue<string> queue=new Queue<string>();HashSet<string> pending=new HashSet<string>();SemaphoreSlim ready=new SemaphoreSlim(0);public LanRdpService Lan {get;private set;}
 public Monitor(){string pf=Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);Exe=System.IO.Path.Combine(pf,"Tailscale","tailscale.exe");if(!File.Exists(Exe)){string x=(Environment.GetEnvironmentVariable("PATH")??"").Split(';').Select(p=>System.IO.Path.Combine(p.Trim('"'),"tailscale.exe")).FirstOrDefault(File.Exists);if(x!=null)Exe=x;}Lan=new LanRdpService((args,timeout,token)=>{var r=Core.Run(Exe,args,timeout,token);return r.Exit==0?r.Output:"";});Lan.Invalidated+=ClearLan;}
 public void Start(){for(int i=0;i<4;i++)Task.Run((Func<Task>)Worker);timer=new System.Threading.Timer(x=>Refresh(),null,0,15000);}
 void Emit(Snapshot s){var h=Changed;if(h!=null&&!stop.IsCancellationRequested)h(s);}
 public void Refresh(){if(Interlocked.CompareExchange(ref busy,1,0)!=0)return;Task.Run(()=>{try{Interlocked.Increment(ref Rounds);Snapshot s;if(!File.Exists(Exe))s=new Snapshot{Message="未找到 Tailscale。请安装并登录官方 Tailscale 客户端。"};else{var r=Core.Run(Exe,"status --json",5000,stop.Token);if(r.Exit!=0)s=new Snapshot{Message="无法读取 Tailscale 状态："+(r.TimedOut?r.Error:(r.Error??"").Trim())+"。请检查本机服务和登录状态。"};else try{s=Core.ParseStatus(r.Output);}catch(Exception e){s=new Snapshot{Message="Tailscale 数据解析失败："+e.Message};}}lock(sync){current=Core.CarryPaths(current,s);Emit(Clone(current));if(s.Valid)foreach(var d in s.Devices.Where(d=>!d.Self&&d.OnlineKnown&&d.Online)){if(pending.Add(d.Id)){queue.Enqueue(d.Id);ready.Release();}}}}catch(Exception e){lock(sync){current=new Snapshot{Message="监控异常："+e.Message};Emit(Clone(current));}}finally{Interlocked.Exchange(ref busy,0);}});}
 async Task Worker(){
  try{while(!stop.IsCancellationRequested){
   await ready.WaitAsync(stop.Token);
   string id,ip;long epoch;bool windows;
   lock(sync){id=queue.Dequeue();var d=current.Valid?current.Devices.FirstOrDefault(x=>x.Id==id&&x.OnlineKnown&&x.Online&&!x.Self):null;if(d==null){pending.Remove(id);continue;}ip=d.IP;epoch=d.Generation;windows=d.Windows;}
   IPAddress parsed;CommandResult r=null;
   if(IPAddress.TryParse(ip,out parsed))r=await Task.Run(()=>{try{return Core.Run(Exe,"ping --c 2 --timeout 2s --until-direct=false "+ip,5500,stop.Token);}catch(Exception ex){return new CommandResult{Exit=-1,Error=ex.Message};}});
   lock(sync){var d=current.Valid?current.Devices.FirstOrDefault(x=>x.Id==id&&x.OnlineKnown&&x.Online&&!x.Self&&x.IP==ip&&x.Generation==epoch):null;
    if(d!=null){d.Path=r==null?"无法确认（无有效 IP）":r.Exit==0?Core.ParsePath(r.Output):"无法确认（探测失败/超时）";d.LatencyMs=r!=null&&r.Exit==0?Core.ParseLatency(r.Output):"—";d.Checked=DateTime.Now.ToString("HH:mm:ss");if(d.Path!="直连"||!d.Windows)d.Lan=null;Emit(Clone(current));}else windows=false;
   }
   LanRdpResult lan=null;
   if(windows){if(r==null||r.Exit!=0||Core.ParsePath(r.Output)!="直连")lan=new LanRdpResult(null,"没有当前直连端点",0);else lan=await Task.Run(()=>Lan.Verify(id,ip,r.Output,stop.Token));}
   lock(sync){pending.Remove(id);var d=current.Valid?current.Devices.FirstOrDefault(x=>x.Id==id&&x.OnlineKnown&&x.Online&&!x.Self&&x.IP==ip&&x.Generation==epoch):null;
    if(d!=null){if(lan!=null&&d.Windows){var end=LanRdpService.ParseCandidate(d.CurAddr);d.Lan=lan.Address==null||(end!=null&&r!=null&&end.Equals(LanRdpService.PingEndpoint(r.Output,ip)))?lan:null;}Emit(Clone(current));}
    else if(current.Valid&&current.Devices.Any(x=>x.Id==id&&x.OnlineKnown&&x.Online&&!x.Self)&&pending.Add(id)){queue.Enqueue(id);ready.Release();}
   }
  }}catch(OperationCanceledException){}catch(Exception e){if(!stop.IsCancellationRequested)Emit(new Snapshot{Message="探测异常："+e.Message});}
 }
 static Snapshot Clone(Snapshot s){return new Snapshot{Valid=s.Valid,Message=s.Message,ListUpdated=s.ListUpdated,Devices=s.Devices.Select(d=>d.Copy()).ToList()};}
 void ClearLan(){lock(sync){foreach(var d in current.Devices)d.Lan=null;Emit(Clone(current));}}
 public async Task<LanRdpResult> CheckLaunch(string id,string ip,long epoch,LanRdpResult old){
  var result=await Task.Run(()=>Lan.Verify(id,ip,null,stop.Token)).ConfigureAwait(false);
  lock(sync){var d=current.Valid?current.Devices.FirstOrDefault(x=>x.Id==id&&x.IP==ip&&x.Generation==epoch&&x.CanRdp):null;
   if(d==null||stop.IsCancellationRequested)return null;
   if(!Lan.IsCurrent(old)||!Lan.IsCurrent(result)||result.Address!=old.Address){d.Lan=new LanRdpResult(null,result.Address==null?result.Reason:"地址或路由已变化，请等待重新检测",result.NetworkVersion);Emit(Clone(current));return null;}
   return result;
  }
 }
 public void Dispose(){if(Interlocked.Exchange(ref disposed,1)!=0)return;stop.Cancel();if(timer!=null)timer.Dispose();Lan.Invalidated-=ClearLan;Lan.Dispose();}
}

public class FloatForm:Form {
 public ListBox List=new ListBox();public event Action RestoreRequested;Point drag,dragOrigin;bool dragging,dragStarted;Settings settings;Snapshot current=new Snapshot();Font bold;ContextMenuStrip closeMenu;
 public FloatForm(Settings s){settings=s;AutoScaleMode=AutoScaleMode.None;Text="Tailscale Auto 悬浮监控";FormBorderStyle=FormBorderStyle.None;TopMost=true;ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;BackColor=Color.White;Font=new Font("Microsoft YaHei UI",9.5f);bold=new Font(Font,FontStyle.Bold);DoubleBuffered=true;List.ItemHeight=22;MinimumSize=new Size(182,0);MaximumSize=new Size(182,430);Size=new Size(182,38);AutoScroll=true;Location=new Point(s.X,s.Y);Opacity=Math.Max(35,Math.Min(100,s.Opacity))/100.0;closeMenu=new ContextMenuStrip();closeMenu.Items.Add("关闭悬浮窗",null,(a,e)=>HideFloating());ContextMenuStrip=closeMenu;SizeChanged+=(a,e)=>RoundCorners();RoundCorners();Scroll+=(a,e)=>Invalidate();MouseWheel+=(a,e)=>Invalidate();MouseDown+=(a,e)=>{if(e.Button==MouseButtons.Right)return;if(e.Button==MouseButtons.Left){if(e.Clicks==2){dragging=false;var h=RestoreRequested;if(h!=null)h();}else{drag=PointToClient(Cursor.Position);dragOrigin=Cursor.Position;dragging=true;dragStarted=false;}}};MouseUp+=(a,e)=>dragging=false;MouseMove+=(a,e)=>{if(dragging&&e.Button==MouseButtons.Left){var c=Cursor.Position;if(!dragStarted&&!new Rectangle(dragOrigin.X-SystemInformation.DragSize.Width/2,dragOrigin.Y-SystemInformation.DragSize.Height/2,SystemInformation.DragSize.Width,SystemInformation.DragSize.Height).Contains(c))dragStarted=true;if(dragStarted)Location=new Point(c.X-drag.X,c.Y-drag.Y);}};LocationChanged+=(a,e)=>{settings.X=Left;settings.Y=Top;settings.Save();};FormClosing+=(a,e)=>{if(e.CloseReason==CloseReason.UserClosing){e.Cancel=true;HideFloating();}};Disposed+=(a,e)=>{bold.Dispose();List.Dispose();};}
 public void ApplyLanguage(){Text=Lang.Chinese?"Tailscale Auto 悬浮监控":"Tailscale Auto Floating Monitor";if(closeMenu!=null&&closeMenu.Items.Count>0)closeMenu.Items[0].Text=Lang.Tr("关闭悬浮窗");Invalidate();}
 void RoundCorners(){using(var path=new System.Drawing.Drawing2D.GraphicsPath()){int d=8;path.AddArc(0,0,d,d,180,90);path.AddArc(Width-d,0,d,d,270,90);path.AddArc(Width-d,Height-d,d,d,0,90);path.AddArc(0,Height-d,d,d,90,90);path.CloseFigure();var old=Region;Region=new Region(path);if(old!=null)old.Dispose();}}
 public void HideFloating(){Hide();settings.Floating=false;settings.Save();}
 public static Color DotColor(Device d,bool valid){if(d.Self)return Palette.Blue;if(!valid||!d.OnlineKnown)return Color.Gray;if(!d.Online)return Color.FromArgb(166,166,166);if(d.Path=="直连")return Palette.Green;if(d.Path.StartsWith("中继"))return Palette.Orange;return Color.Gray;}
 public static bool Hollow(Device d,bool valid){return !d.Self&&(!valid||!d.OnlineKnown||(d.Online&&d.Path!="直连"&&!d.Path.StartsWith("中继")));}
 public static Color NameColor(Device d,bool valid){return d.Self?Palette.Blue:valid&&d.OnlineKnown&&!d.Online?Color.FromArgb(166,166,166):Palette.Ink;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;int y=AutoScrollPosition.Y+5;for(int i=0;i<current.Devices.Count;i++){var d=current.Devices[i];float center=y+i*List.ItemHeight+List.ItemHeight/2f;var dot=new RectangleF(12,center-4.5f,9,9);using(var brush=new SolidBrush(DotColor(d,current.Valid)))using(var pen=new Pen(DotColor(d,current.Valid),1.5f)){if(Hollow(d,current.Valid))e.Graphics.DrawEllipse(pen,dot);else e.Graphics.FillEllipse(brush,dot);}using(var brush=new SolidBrush(NameColor(d,current.Valid)))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap,LineAlignment=StringAlignment.Center})e.Graphics.DrawString(settings.DisplayName(d),d.Self?bold:Font,brush,new RectangleF(32,center-List.ItemHeight/2f,ClientSize.Width-40,List.ItemHeight),format);}}
 public void Render(Snapshot s){var next=new Snapshot{Valid=s.Valid,Message=s.Message,Devices=Core.SortDevices(s.Devices,d=>settings.DisplayName(d))};int count=Math.Max(current.Devices.Count,next.Devices.Count);for(int i=0;i<count;i++){var before=i<current.Devices.Count?current.Devices[i]:null;var after=i<next.Devices.Count?next.Devices[i]:null;if(before==null||after==null||before.Id!=after.Id||before.Path!=after.Path||before.Online!=after.Online||before.OnlineKnown!=after.OnlineKnown||settings.DisplayName(before)!=settings.DisplayName(after)||s.Valid!=current.Valid)Invalidate(new Rectangle(0,AutoScrollPosition.Y+5+i*List.ItemHeight,Width,List.ItemHeight));}current=next;while(List.Items.Count>next.Devices.Count)List.Items.RemoveAt(List.Items.Count-1);for(int i=0;i<next.Devices.Count;i++){string name=settings.DisplayName(next.Devices[i]);if(i==List.Items.Count)List.Items.Add(name);else if(Convert.ToString(List.Items[i])!=name){List.Items[i]=name;Invalidate(new Rectangle(0,AutoScrollPosition.Y+5+i*List.ItemHeight,Width,List.ItemHeight));}}var scroll=new Size(0,next.Devices.Count*List.ItemHeight+10);if(AutoScrollMinSize!=scroll)AutoScrollMinSize=scroll;var size=new Size(182,Math.Min(420,Math.Max(38,scroll.Height)));if(Size!=size)Size=size;Bounds=Core.VisibleBounds(Bounds,Screen.AllScreens.Select(x=>x.WorkingArea).ToArray());}
}
