public static class UiMetrics {
 public const int Margin=32,FooterHeight=40,MinimumWidth=1020,MinimumHeight=520;
 public static int RowWidth(int panelWidth,float scale){return Math.Max(0,panelWidth-SystemInformation.VerticalScrollBarWidth-(int)(2*Margin*scale));}
 public static float RightEdge(float panelWidth,float scale){return panelWidth/scale-SystemInformation.VerticalScrollBarWidth/scale-Margin;}
}
