public static class UiShape {
 public static System.Drawing.Drawing2D.GraphicsPath Rounded(float x,float y,float width,float height,float radius){
  var path=new System.Drawing.Drawing2D.GraphicsPath();float d=radius*2;
  path.AddArc(x,y,d,d,180,90);path.AddArc(x+width-d,y,d,d,270,90);
  path.AddArc(x+width-d,y+height-d,d,d,0,90);path.AddArc(x,y+height-d,d,d,90,90);
  path.CloseFigure();return path;
 }
}
public static class UiAssets {
 static Image Load(string name,string resourceName){string path=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",name);try{var assembly=System.Reflection.Assembly.GetExecutingAssembly();using(var stream=assembly.GetManifestResourceStream(resourceName)){if(stream!=null)using(var source=Image.FromStream(stream))return new Bitmap(source);}if(!File.Exists(path)){Debug.WriteLine("Tailscale Auto UI asset missing: "+path);return null;}using(var source=Image.FromFile(path))return new Bitmap(source);}catch(Exception ex){Debug.WriteLine("Tailscale Auto UI asset load failed: "+name+"; "+ex.Message);return null;}}
 public static readonly Image Windows=Load("windows.png","TailscaleAuto.assets.windows.png");
 public static readonly Image Ios=Load("ios.png","TailscaleAuto.assets.ios.png");
 public static readonly Image Android=Load("android.png","TailscaleAuto.assets.android.png");
 public static Image ForOS(string os){string value=(os??"").ToLowerInvariant();return value.Contains("ios")||value.Contains("ipados")?Ios:value.Contains("android")?Android:value.Contains("windows")?Windows:null;}
 static readonly Dictionary<Image,Image> grayImages=new Dictionary<Image,Image>();
 public static Image Gray(Image source){if(source==null)return null;Image result;if(grayImages.TryGetValue(source,out result))return result;var bitmap=new Bitmap(source.Width,source.Height);for(int x=0;x<source.Width;x++)for(int y=0;y<source.Height;y++){var c=((Bitmap)source).GetPixel(x,y);bitmap.SetPixel(x,y,Color.FromArgb(c.A,140,140,140));}grayImages[source]=bitmap;return bitmap;}
}
public class RdpActionButton:Button {
 bool hovered,pressed;
 public RdpActionButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);MouseEnter+=(a,e)=>{hovered=true;Invalidate();};MouseLeave+=(a,e)=>{hovered=false;pressed=false;Invalidate();};MouseDown+=(a,e)=>{if(e.Button==MouseButtons.Left&&Enabled){pressed=true;Invalidate();}};MouseUp+=(a,e)=>{if(e.Button==MouseButtons.Left){pressed=false;Invalidate();}};}
 protected override void OnResize(EventArgs e){base.OnResize(e);if(Width<8||Height<8)return;using(var path=UiShape.Rounded(0,0,Width,Height,5)){var old=Region;Region=new Region(path);if(old!=null)old.Dispose();}}
 protected override void OnPaint(PaintEventArgs e){
  Color fill=!Enabled?Palette.Disabled:pressed?Color.FromArgb(197,222,210):hovered?Palette.AccentSoft:Color.White;
  Color border=!Enabled?Palette.Border:Palette.Accent, text=!Enabled?Palette.Muted:Palette.Accent;
  e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
  // Keep the one-pixel stroke fully inside the rounded clipping region.
  using(var shape=UiShape.Rounded(0,0,Width,Height,5))
  using(var stroke=UiShape.Rounded(1.5f,1.5f,Width-3,Height-3,3.5f))
  using(var brush=new SolidBrush(fill))
  using(var pen=new Pen(border,1f)){
   e.Graphics.FillPath(brush,shape);
