 void Navigate(string id,Keys key){SelectDevice(id);if((key&Keys.KeyCode)==Keys.Apps||((key&Keys.Shift)==Keys.Shift&&(key&Keys.KeyCode)==Keys.F10)){rowMenu.Show(DeviceRows[id],new Point(20,20));return;}if((key&Keys.Control)==Keys.Control&&(key&Keys.KeyCode)==Keys.C){CopySelectedIP();return;}int index=devices.FindIndex(d=>d.Id==id);if((key&Keys.KeyCode)==Keys.Up)index--;if((key&Keys.KeyCode)==Keys.Down)index++;if(index>=0&&index<devices.Count){var row=DeviceRows[devices[index].Id];SelectDevice(devices[index].Id);row.Focus();DeviceList.ScrollControlIntoView(row);}}
void UpdateStatus(){bool active=DateTime.Now<noticeUntil;string message=!latest.Valid?latest.Message+(active&&noticeWarning?"；"+notice:""):active?notice:"";message=message??"";string displayMessage=Lang.StatusMessage(message);bool visible=displayMessage.Length>0;if(status.Text!=displayMessage)status.Text=displayMessage;if(statusShown!=visible||status.Height!=(visible?(int)(32*scale):0)){int offset=-DeviceList.AutoScrollPosition.Y;SuspendLayout();statusShown=visible;status.Visible=visible;status.Height=visible?(int)(32*scale):0;ResumeLayout();ArrangeRows();DeviceList.AutoScrollPosition=new Point(0,offset);ArrangeFooterLinks();}}
 void ShowNotice(string message,int seconds,bool warning=false){if(!warning&&noticeWarning&&DateTime.Now<noticeUntil)return;noticeWarning=warning;notice=message;noticeUntil=DateTime.Now.AddSeconds(seconds);UpdateStatus();}
 public void SetAlias(string id,string value){value=new string((value??"").Where(c=>!Char.IsControl(c)).ToArray()).Trim();if(value.Length>80)throw new ArgumentException("别名最多80个字符");if(value.Length==0)settings.Aliases.Remove(id);else settings.Aliases[id]=value;settings.Save();Render(latest);}
 void EditAlias(){var d=Selected();if(d==null)return;using(var dialog=new Form{Text=Lang.Tr("本地显示别名"),StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(420,160),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,Font=Font}){var original=new Label{Text=Lang.Tr("原名：")+d.Name,AutoEllipsis=true,Left=16,Top=16,Width=388};var input=new TextBox{Left=16,Top=48,Width=388,MaxLength=80,Text=settings.DisplayName(d)};var hint=new Label{Text=Lang.Tr("仅保存到本机；留空恢复原名（最多80字）。"),Left=16,Top=82,Width=388};var ok=new Button{Text=Lang.Tr("保存"),DialogResult=DialogResult.OK,Left=240,Top=118};var cancel=new Button{Text=Lang.Tr("取消"),DialogResult=DialogResult.Cancel,Left=328,Top=118};dialog.Controls.AddRange(new Control[]{original,input,hint,ok,cancel});dialog.AcceptButton=ok;dialog.CancelButton=cancel;if(dialog.ShowDialog(this)==DialogResult.OK)SetAlias(d.Id,input.Text);}}

 public void Render(Snapshot s){ArrangeTop();string order=String.Join("|",devices.Select(d=>d.Id));latest=s;if(s.Valid&&s.ListUpdated!=DateTime.MinValue)LastListUpdated=s.ListUpdated;if(s.Valid)devices=Core.SortDevices(s.Devices.Select(d=>d.Copy()),d=>settings.DisplayName(d));else foreach(var d in devices){d.Path="无法确认";d.Checked="—";d.LatencyMs="—";d.Online=false;d.OnlineKnown=false;}var ids=new HashSet<string>(devices.Select(d=>d.Id));bool structure=order!=String.Join("|",devices.Select(d=>d.Id));foreach(var id in DeviceRows.Keys.Where(id=>!ids.Contains(id)).ToArray()){var row=DeviceRows[id];DeviceList.Controls.Remove(row);row.Dispose();DeviceRows.Remove(id);structure=true;}foreach(var d in devices){DeviceRow row;if(!DeviceRows.TryGetValue(d.Id,out row)){row=new DeviceRow();row.SelectRequested+=SelectDevice;row.CopyRequested+=id=>CopyIP(id);row.RdpRequested+=LaunchRdp;row.LanRequested+=LaunchLanRdp;row.NavigateRequested+=Navigate;row.MenuRequested+=(id,point)=>{SelectDevice(id);rowMenu.Show(point);};DeviceRows.Add(d.Id,row);DeviceList.Controls.Add(row);structure=true;}row.UpdateDevice(d,s.Valid,settings.DisplayName(d));SetLanButton(row);}if(SelectedId!=null&&!ids.Contains(SelectedId))SelectedId=null;if(structure)ArrangeRows();string time=LastListUpdated==DateTime.MinValue?"—":LastListUpdated.ToString("HH:mm:ss");Summary.Text=s.Valid?Lang.Summary(devices.Count,devices.Count(d=>d.OnlineKnown&&d.Online),time):Lang.SummaryUnknown(devices.Count,time);UpdateStatus();Floating.Render(new Snapshot{Valid=s.Valid,Message=s.Message,Devices=devices});}
 public void Restore(){Show();WindowState=FormWindowState.Normal;Activate();}
 public void Exit(){exiting=true;if(Monitoring!=null)Monitoring.Dispose();Close();}
 protected override void WndProc(ref Message m){if(m.Msg==RestoreMessage){Restore();return;}base.WndProc(ref m);}
}
public static class Program {
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr hwnd,int msg,IntPtr w,IntPtr l);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string cls,string title);
 delegate bool WindowEnum(IntPtr h,IntPtr p);
 [DllImport("user32.dll")]static extern bool EnumWindows(WindowEnum callback,IntPtr p);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr GetProp(IntPtr h,string name);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder text,int count);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 static IntPtr ExistingWindow(){IntPtr found=IntPtr.Zero;EnumWindows((h,p)=>{if(GetProp(h,"TailscaleAuto.MainWindow.296590A7")!=IntPtr.Zero){found=h;return false;}var title=new StringBuilder(256);GetWindowText(h,title,256);if(title.ToString()=="Tailscale Auto"||title.ToString().StartsWith("Tailscale Auto v")){uint pid;GetWindowThreadProcessId(h,out pid);try{var process=Process.GetProcessById((int)pid);if(process.ProcessName=="TailscaleAuto"){found=h;return false;}}catch{}}return true;},IntPtr.Zero);return found;}
 [STAThread]public static void Main(string[] args){if(args.Contains("--self-test")){try{Environment.Exit(SelfTest());}catch(Exception ex){Console.WriteLine(ex.GetType().Name+": "+ex.Message);Console.WriteLine(ex.StackTrace);Environment.Exit(1);}return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool created;using(var mutex=new Mutex(true,"Local\\TailscaleAuto_296590A7",out created)){if(!created){for(int i=0;i<30;i++){IntPtr h=ExistingWindow();if(h!=IntPtr.Zero){PostMessage(h,MainForm.RestoreMessage,IntPtr.Zero,IntPtr.Zero);break;}Thread.Sleep(100);}return;}Application.Run(new MainForm(false));}}
 static int SelfTest(){var errors=new List<string>();Action<bool,string> check=(v,n)=>{Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)errors.Add(n);};check(Core.ParsePath("pong from a (100.1.2.3) via 192.168.1.2:123 in 3ms")=="直连","direct parse");check(Core.ParsePath("pong from a (100.1.2.3) via DERP(hkg) in 30ms")=="中继（DERP）","relay parse");check(Core.ParsePath("timeout")=="无法确认","failure parse");check(Core.ParseLatency("pong from a via 192.168.1.2:123 in 3ms")=="3.0 ms","latency parse");var parsed=Core.ParseStatus("{\"BackendState\":\"Running\",\"Self\":{\"HostName\":\"pc\",\"OS\":\"windows\",\"Online\":true,\"TailscaleIPs\":[\"100.1.2.3\",\"fd7a::1\"]},\"Peer\":{}}");check(parsed.Valid&&parsed.Devices[0].IP=="100.1.2.3","status JSON array IP");check(Core.ParsePath("pong from a via strange in 3ms")=="无法确认","unknown route");var d=new Device{OS="windows",Online=true,OnlineKnown=true,Path="直连",IP="100.1.2.3"};check(Core.RdpArguments(d)=="/v:100.1.2.3","rdp target");d.Self=true;check(!d.CanRdp,"self no rdp");d.Self=false;d.IP="x & calc";check(!d.CanRdp,"invalid target blocked");check(Core.VisibleBounds(new Rectangle(-9999,-9999,320,200),new[]{new Rectangle(0,0,1920,1080)}).Location==Point.Empty,"offscreen clamp");Application.EnableVisualStyles();using(var f=new MainForm(true)){f.Show();var s=new Snapshot{Valid=true,Message="test"};for(int i=0;i<100;i++)s.Devices.Add(new Device{Id=i.ToString(),Name="device"+i,OS=i==0?"windows":"linux",IP="100.1.2.3",Online=i%2==0,OnlineKnown=true,Self=i==0});f.Render(s);check(f.DeviceRows.Count==100,"100 device render");f.FloatToggle.Checked=false;f.FloatToggle.Checked=true;Application.DoEvents();check(f.Floating.Visible&&f.Floating.TopMost&&f.Floating.Height<=430,"floating bounded topmost");f.Alpha.Value=35;check(f.Floating.Opacity==0.35&&f.Opacity==1,"opacity isolation");f.Hide();check(f.Floating.Visible,"float survives main hide");f.Render(new Snapshot{Message="failed"});check(!f.DeviceRows["1"].Valid,"status failure unknown");f.Exit();}Console.WriteLine("Failures: "+errors.Count);return errors.Count==0?0:1;}
}
